<section class="dashboard-content"><div class="dashboard-heading"><div class="eyebrow">فرصت‌های منتخب</div><h1>پروژه‌های ذخیره‌شده</h1></div><section class="dash-card"><div class="job-list"><?php foreach($jobs as $job):?><article class="job-item"><div><h3><?=e($job['title'])?></h3><p><?=e($job['description'])?></p><small><?=e($job['employer_name']?:'کارفرما')?> · <?=e($job['budget_min'])?> تا <?=e($job['budget_max'])?> دلار</small></div><form method="post" action="<?=url('/dashboard/freelancer/saved-jobs')?>"><?=csrf_field()?><input type="hidden" name="job_id" value="<?=e($job['id'])?>"><button class="action-button suspend">حذف از ذخیره‌ها</button></form></article><?php endforeach;?><?php if(!$jobs):?><div class="empty-state">هنوز پروژه‌ای ذخیره نکرده‌اید.</div><?php endif;?></div></section></section>